    for m in [lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),
              lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]:
        n=norm([m(r,c) for r,c in s])
        if n not in res: res.append(n)
    return res
