def find_trans(I,O,obj,bgI,bgO):
    h=len(O);w=len(O[0])
    rmin=min(x for x,y in obj); cmin=min(y for x,y in obj)
    relcol={(x-rmin,y-cmin):I[x][y] for x,y in obj}
    hits=[]
    for r0 in range(h):
        for c0 in range(w):
            ok=True
            for (dx,dy),v in relcol.items():
                if not(0<=r0+dx<h and 0<=c0+dy<w) or O[r0+dx][c0+dy]!=v: ok=False;break
            if ok: hits.append((r0,c0))
    return hits
